NULL),(74,51,'sirt-woo-2024-11-xss-admin','See available updates','http://nova-poshak.test/wp-admin/update-core.php?','unactioned','',NULL,NULL),(75,51,'sirt-woo-2024-11-xss-admin','Dismiss','#','actioned','',NULL,NULL),(76,52,'paypal-braintree-sdk-depreciation-2025-02-20-button','Upgrade now','http://nova-poshak.test/wp-admin/wp-admin/plugins.php','actioned','',NULL,NULL),(77,53,'uk-vat-notice-button-2025-04-30','Learn more about this extension','https://wordpress.org/plugins/eu-vat-for-woocommerce/','actioned','',NULL,NULL),(78,54,'paypal-braintree-sdk-depreciation-2025-05-30-button','Update now','http://nova-poshak.test/wp-admin/wp-admin/plugins.php','unactioned','',NULL,NULL),(79,55,'woo-dotcom-course-2026-06-09','Visit the course','https://wordpress.com/support/courses/build-your-store-with-woocommerce/','actioned','',NULL,NULL),(80,56,'learn-more','بیشتر بدانید','https://woocommerce.com/document/managing-orders/?utm_source=inbox&utm_medium=product','actioned','',NULL,NULL);
